function SHELL_RADIUS(R, d, N, k):
    require d >= 1, N >= 2, 0 <= k <= N
    if k = N: return 0
    z <- log1p(-k/N)          # = log(1 - k/N), accurate for small k/N
    return R * exp(z / d)

function SHELL_DEPTH(R, d, N, k):
    require d >= 1, N >= 2, 0 <= k < N
    z <- log1p(-k/N)
    return -R * expm1(z / d)  # = R - R*exp(z/d), no cancellation

function PEELING_TABLE(R, d, N):
    T <- empty list
    for k = 1 to N-1:
        r     <- SHELL_RADIUS(R, d, N, k)
        delta <- SHELL_DEPTH(R, d, N, k)
        append (k, r, delta, d*delta) to T
    return T

algorithms.code:
"""Numerically stable evaluation of the equal-volume peeling."""

from __future__ import annotations

import math
from typing import List, Tuple


def shell_radius(R: float, d: int, N: int, k: int) -> float:
    """Radius r_k = R (1 - k/N)^(1/d) of the k-th sphere.

    Evaluated as R * exp(log1p(-k/N) / d): the log1p keeps the logarithm
    accurate for small k/N, and the exponential avoids a fractional power.
    """
    if d < 1 or N < 2 or not (0 <= k <= N):
        raise ValueError("require d >= 1, N >= 2, 0 <= k <= N")
    if k == N:
        return 0.0
    return R * math.exp(math.log1p(-k / N) / d)


def shell_depth(R: float, d: int, N: int, k: int) -> float:
    """Depth delta_k = R - r_k, free of cancellation error.

    Direct subtraction R - r_k loses all significant digits once d is large,
    because r_k -> R.  Writing the depth as -R * expm1(z) with
    z = log1p(-k/N)/d keeps full relative precision for every d.
    """
    if d < 1 or N < 2 or not (0 <= k < N):
        raise ValueError("require d >= 1, N >= 2, 0 <= k < N")
    return -R * math.expm1(math.log1p(-k / N) / d)


def peeling_table(R: float, d: int, N: int) -> List[Tuple[int, float, float, float]]:
    """Rows (k, r_k, depth_k, d*depth_k) for k = 1, ..., N-1."""
    return [(k, shell_radius(R, d, N, k), shell_depth(R, d, N, k),
             d * shell_depth(R, d, N, k)) for k in range(1, N)]

algorithms.pseudocode:
function RESCALED_THICKNESS(R, d, N):
    return d * SHELL_DEPTH(R, d, N, 1)

function MONOTONE_ASCENT(R, N, D):
    Lambda <- log(N/(N-1))
    V <- [ RESCALED_THICKNESS(R, d, N) for d = 1..D ]
    for i = 1 to D-1:
        assert V[i] <= V[i+1] + tol          # monotonicity
    assert V[D] <= R*Lambda + tol            # the limit is the supremum
    assert |V[1] - R/N| <= tol               # exactness in dimension one
    return V

function DIMENSION_FOR_RELATIVE_ACCURACY(N, eps):
    Lambda <- log(N/(N-1))
    # relative shortfall <= Lambda/(d + Lambda) <= eps
    return max(1, ceil(Lambda*(1-eps)/eps))
